package net.vectolyn.cloud.database;

import java.util.Objects;
import net.vectolyn.cloud.config.secret.Secret;

/**
 * The two database passwords from {@code secrets/vectolyn.env}. Both are generated by the cloud
 * ({@code VECTOLYN_DB_ROOT_PASSWORD}, {@code VECTOLYN_DB_PASSWORD}); for an external server the
 * operator enters the application password.
 *
 * @param root password of the MariaDB {@code root} user; not used for an external server
 * @param application password of the application user
 */
public record DatabaseSecrets(Secret root, Secret application) {

    /**
     * Checks the values.
     *
     * @param root the root password
     * @param application the application password
     */
    public DatabaseSecrets {
        Objects.requireNonNull(root, "root");
        Objects.requireNonNull(application, "application");
    }

    @Override
    public String toString() {
        return "DatabaseSecrets[root=" + Secret.MASK + ", application=" + Secret.MASK + "]";
    }
}
